          '{"events":[[1,"day_speech",{"playerId":1,"text":"原文事件"}]]}',
        );
        expect(captured[0]).toContain("werewolf-game");
        if (locale === "en")
          expect(captured[0].replace("原文事件", "")).not.toMatch(/[\u4e00-\u9fff]/);
      } finally {
        await provider.close();
      }
    }),
  );
});

