    if (request.allowedTools.includes("kill_vote")) {
      this.voteOrder.push(request.actorId);
      return {
        name: "kill_vote",
        args: { target_id: this.wolfTargetId, abstain: false },
      };
    }

    if (request.allowedTools.includes("guard")) {
