    let knifeCalls = 0;
    if (mutation === "wolf_revive")
      await new DeathResolution(game.world, [], new ToolGateway(), new EventRegistry(), {
        day: 1,
        phase: Phase.Day,
        gameOver: false,
        result: null,
      }).resolve(
        [6],
        { 6: [DeathCause.Shot] },
