        if (req.allowedTools.includes("use_potion"))
          return {
            name: "use_potion" as const,
            args: {
              target_id: cycle === 2 && mode === "pending_poison" ? 3 : 4,
              potion_type:
                cycle === 2 && mode === "pending_poison"
                  ? (PotionType.Poison as const)
                  : (PotionType.None as const),
            },
          };
        if (req.allowedTools.includes("speak"))
          return { name: "speak" as const, args: { text: "Raw" } };
        if (req.allowedTools.includes("vote"))
          return {
            name: "vote" as const,
            args: {
              target_id:
                cycle === 1
                  ? mode === "abstain"
                    ? null
                    : mode === "idiot"
                      ? 4
                      : mode === "keeper_dead"
                        ? 3
                        : 1
                  : null,
              abstain: cycle !== 1 || mode === "abstain",
            },
          };
        throw new Error(`unexpected:${req.context.stage}`);
      },
    };
    await game.phaseManager.runSingleCycle(provider);
    cycle = 2;
    await game.phaseManager.runSingleCycle(provider);
    const feedback = game.phaseManager
      .getEvents()
      .filter((event) => event.type === "gravekeeper_reported");
    expect(feedback).toHaveLength(mode.startsWith("pending_") ? 1 : 0);
    if (mode.startsWith("pending_")) {
      expect(feedback[0].payload).toEqual({
        actorId: 3,
        targetId: 1,
        exileDay: 1,
        receivedDay: 2,
        result: { kind: "camp", camp: "wolf" },
      });
      expect(game.world.getAliveEntityIds()).not.toContain(3);
    }
  });

