          }),
        },
      };
    if (profile.metadata.role === Role.Guard)
      return {
        ...profile,
        runtime: {
          ...profile.runtime,
          nightStages: [],
          wolfTeam: {
            recognizedByPack: true,
            recognizes: "none" as const,
            canChat: true,
            canVoteForKill: false,
          },
        },
      };
