      getDefaultRoleCatalog().runtime(Role.Wolf)?.wolfTeam,
    );
    (wolf.privateState as Record<string, unknown>).unmasked = true;
    expect(resolveInspection(world, 1, "combined", catalog)).toEqual({
      kind: "combined",
      role: "wolf",
      camp: "wolf",
    });
