          required_any_tools: ["demon_hunt"],
        },
      },
      ...(deadlineAtMs === undefined ? {} : { deadlineAtMs }),
    };
  bindDemonHunterRequest(f.world, request);
  expect(demonHunterRequestScope(f.world, request)).toBe(scope);
  return { scope, request };
}
