});

test("scope wrapper cannot be rewritten to revive old identity", () => {
  const { world, scopes } = targets(),
    s = scopes[1]!;
  expect(Object.isFrozen(s)).toBe(true);
  s.life.alive = false;
  s.life.alive = true;
  expect(Reflect.set(s, "version", 2)).toBe(false);
