/**
 * 单元测试：验证机械狼人捕获枪的原生运行所有权。输入为原内存能力与受控操作；既有字面结果及原枪引用为预期，不运行模型传输或重建 fixture。
 */
import { expect, test } from "bun:test";
import { bootstrapGame } from "../../../../src/app/bootstrap";
import { COMPONENT, Camp, Role, Phase, WinCondition, type BoardConfig, type RoleComponent } from "../../../../src/core";
import { sixPlayerMvpConfig } from "../../../../src/runtime/scenarios/six_player_mvp";
import { getMechanicalState } from "../../../../src/game/mechanisms/roles/mechanical_wolf/state";
import { DeathCause } from "../../../../src/core/domain/deaths";
import { mechanicalDeathHook } from "../../../../src/game/mechanisms/roles/mechanical_wolf/death_hook";
import {
  advanceMechanicalNight,
  learnMechanicalRole,
} from "../../../../src/game/mechanisms/roles/mechanical_wolf/state";

const deck = [Role.MechanicalWolf, Role.Wolf, Role.Psychic, Role.Witch, Role.Guard, Role.Villager];

function board(roles = deck): BoardConfig {
  return {
    ...sixPlayerMvpConfig,
    boardSize: roles.length,
    roleSetups: [...new Set(roles)].map((role) => ({
      role,
      count: roles.filter((r) => r === role).length,
    })),
    winConditions: [WinCondition.SlaughterCity],
    selfDestruct: { enabledWindows: [] },
  };
}

function fixture(locale: "zh-CN" | "en" = "zh-CN", roles = deck) {
  const config = board(roles),
    game = bootstrapGame(config, { fixedRoles: roles, locale });
  const role = game.world.getComponent(1, COMPONENT.Role)!;
  return { ...game, config, role, state: getMechanicalState(role)! };
}

type Game = ReturnType<typeof fixture>;

for (const revoke of ["camp", "private_state", "owner_state", "learning"] as const)
  test(`${revoke}: an armed mechanical gun stays bound to its original owner and learning through death selection`, async () => {
    const roles = [
        Role.MechanicalWolf,
        Role.Wolf,
        Role.Hunter,
        Role.Witch,
        Role.Guard,
        Role.Villager,
      ],
      game = fixture("en", roles);
    learnMechanicalRole(game.state, 3, Role.Hunter, 1);
    advanceMechanicalNight(game.state, 2);
    game.world.getComponent(1, COMPONENT.Alive)!.alive = false;
    const gun = game.state.learned!.skill,
      events = [] as ReturnType<Game["phaseManager"]["getEvents"]>;
    const permit = game.world.openDeathAction(1, "shoot", Phase.Voting, 2);
    try {
      const result = await mechanicalDeathHook(
        game.world,
        [1],
        { 1: [DeathCause.Exile] },
        async () => {
          if (revoke === "camp") game.role.camp = Camp.Good;
          if (revoke === "private_state")
            (game.role as { privateState: Readonly<Record<string, unknown>> }).privateState = {
              ...game.role.privateState,
            };
          if (revoke === "owner_state")
            (game.role.privateState as Record<string, unknown>).mechanical_wolf = { ...game.state };
          if (revoke === "learning")
            (
              game.state as {
                learned: import("@ai-werewolf-arena/game-contract").MechanicalReadLearning | null;
              }
            ).learned = { ...game.state.learned! };
          return { kind: "shot", targetId: 4, deathActionId: permit.id };
        },
        events,
      );
      expect(result).toEqual({ extraDeaths: [], extraDeathSources: {} });
      expect(events).toEqual([]);
      expect(gun).toEqual({ kind: "hunter", canShoot: true, armed: true });
    } finally {
      permit.close();
    }
    expect(game.world.activeDeathActionCount).toBe(0);
  });

/**
 * 单元测试：验证机械狼的独立继承契约及原 owner／frame／reader。输入为内存 fixture、受控回调与畸形修改；原字面值、身份快照和拒绝断言为预期，不执行装配周期、模型或实体传输。
 */
import { createAliveComponent } from "../../../../src/game/observation/component-presentation";
import { expect, test } from "bun:test";
import { COMPONENT } from "../../../../src/core/domain/components/names";

import { createRoleComponent } from "../../../../src/game/observation/role-presentation";
import { Camp, Role } from "../../../../src/core/domain/model";
import { World } from "../../../../src/core/domain/world";
import {
  canMechanicalKnife,
  refreshMechanicalInheritance,
} from "../../../../src/game/mechanisms/roles/mechanical_wolf/inheritance";
import {
  captureMechanicalOwner,
  recordMechanicalModeScope,
} from "../../../../src/game/mechanisms/roles/mechanical_wolf/night_scope";
import {
  freshMechanicalState,
  selectMechanicalMode,
  setMechanicalState,
} from "../../../../src/game/mechanisms/roles/mechanical_wolf/state";

function fixture(otherWolves = 1) {
  const world = new World(),
    actor = world.createEntity();
  const role = createRoleComponent(Role.MechanicalWolf, Camp.Wolf),
    life = createAliveComponent();
  world.addComponent(actor, COMPONENT.Role, role);
  world.addComponent(actor, COMPONENT.Alive, life);
  const state = setMechanicalState(role, freshMechanicalState());
  const others = Array.from({ length: otherWolves }, () => {
    const id = world.createEntity(),
      alive = createAliveComponent();
    world.addComponent(id, COMPONENT.Role, createRoleComponent(Role.WolfKing, Camp.Wolf));
    world.addComponent(id, COMPONENT.Alive, alive);
    return alive;
  });
  const chooseMode = (day: number, mode: "skill" | "kill") => {
    selectMechanicalMode(state, day, mode);
    recordMechanicalModeScope(
      world,
      captureMechanicalOwner(world, actor, () => true)!,
      day,
    );
  };
  return { world, actor, role, life, state, others, chooseMode };
}

test("only assembly or actual complete death commit can acquire the sole-true-Wolf knife fact", () => {
  const f = fixture(),
    before = JSON.stringify(f.state);
  f.chooseMode(2, "kill");
  expect(refreshMechanicalInheritance(f.world, 1)).toEqual([]);
  expect(canMechanicalKnife(f.role, f.world)).toBe(false);
  expect(f.state.hasInheritedKnife).toBe(false);
  // The controller commits the death before invoking the actual-death refresh.
  f.others[0]!.alive = false;
  for (let i = 0; i < 3; i++) expect(canMechanicalKnife(f.role, f.world)).toBe(false);
  expect(f.state.hasInheritedKnife).toBe(false);
  expect(refreshMechanicalInheritance(f.world, 2)).toEqual([
    { actorId: f.actor, day: 2, firstKnifeNight: 3 },
  ]);
  expect(canMechanicalKnife(f.role, f.world)).toBe(false);
  f.chooseMode(3, "kill");
  expect(canMechanicalKnife(f.role, f.world)).toBe(true);
  expect(refreshMechanicalInheritance(f.world, 3)).toEqual([]);
  expect(JSON.parse(before).hasInheritedKnife).toBe(false);
});

test("no transient inheritance when mechanical and the last other Wolf die in the same marked proposal", () => {
  const f = fixture();
  f.others[0]!.alive = false;
  f.life.alive = false;
  expect(refreshMechanicalInheritance(f.world, 2)).toEqual([]);
  expect(f.state.hasInheritedKnife).toBe(false);
  expect(f.state.firstKnifeNight).toBeNull();
});

test("a fact acquired in an earlier committed proposal survives later death and another Wolf's revival", () => {
  const f = fixture();
  f.others[0]!.alive = false;
  refreshMechanicalInheritance(f.world, 2);
  f.chooseMode(3, "kill");
  expect(canMechanicalKnife(f.role, f.world)).toBe(true);
  f.others[0]!.alive = true;
  expect(canMechanicalKnife(f.role, f.world)).toBe(false);
  expect(refreshMechanicalInheritance(f.world, 7)).toEqual([]);
  f.others[0]!.alive = false;
  expect(f.state.firstKnifeNight).toBe(3);
  f.life.alive = false;
  expect(canMechanicalKnife(f.role, f.world)).toBe(false);
  expect(f.state.hasInheritedKnife).toBe(true);
});

test("a lone mechanical at assembly first attacks on night two, with a live chosen kill mode", () => {
  const f = fixture(0);
  expect(refreshMechanicalInheritance(f.world, 1)).toEqual([
    { actorId: 1, day: 1, firstKnifeNight: 2 },
  ]);
  expect(canMechanicalKnife(f.role)).toBe(false);
  expect(canMechanicalKnife(f.role, f.world)).toBe(false);
  f.chooseMode(2, "skill");
  expect(canMechanicalKnife(f.role, f.world)).toBe(false);
  f.chooseMode(3, "kill");
  expect(canMechanicalKnife(f.role, f.world)).toBe(true);
});

/**
