        expect(this).toBeUndefined();
        return attemptCharmTrigger(...args);
      };
    },
    commitCharmDeath,
  });
  const nightEffects = {
    get dreams() {
      trace.push("dreams");
      return dreams;
    },
  };
  expect(() =>
    owner.prepare(
