  for (const actor of game.world.entityIds()) {
    const feed = buildAgentVisibleEventFeed(game.world, [event], actor);
    expect(feed).toHaveLength(actor === 2 ? 1 : 0);
    expect(JSON.stringify(feed)).not.toMatch(/synthetic|source/);
  }
});

