const ability = (id: string): NightAbility<"seer_check"> => ({
  id,
  kind: "seer_check",
  state: { lastTarget: null, lastIsWerewolf: null, lastResult: null, history: [] },
  source: { kind: "gift", actorId: 9 },
  sourceDisclosed: false,
