 * 宽克隆结果不等于后续 JSON 归档接受或行动授权，不推进对局、不写档案或调用模型。
 */
import { expect, test } from "bun:test";
import { Role, Camp } from "@ai-werewolf-arena/game-contract";
import { World } from "../../../src/core/domain/world";
