  Object.defineProperty(mapped!, "missed", { configurable: true, get() { trace.push("missed"); return false; } });
  const registry = { get onVotedOut() {
    trace.push("callee");
    return function(this: unknown, givenWorld: World, target: number, givenEvents: GameEvent[]) {
      trace.push("hook");
      expect(this).toBe(registry);
      expect(givenWorld).toBe(world);
      expect(target).toBe(3);
      expect(givenEvents).toBe(events);
      return { prevented: false, removed: hookRemoved, reason: "literal_original_hook" };
    };
  } };
  Object.defineProperty(events, "push", { get() {
    trace.push("push");
    return function(this: GameEvent[], event: GameEvent) {
      trace.push("push-call");
      Object.defineProperty(mapped!, "missed", { configurable: true, get() { trace.push("missed-late"); return true; } });
      return Array.prototype.push.call(this, event);
    };
  } });
  const removed = resolveMappedExile({
    get eventRegistry() { trace.push("registry"); return registry; },
    get world() { trace.push("world"); return world; },
    get events() { trace.push("events"); return events; },
    get animalUnit() { trace.push("animal"); return undefined; },
  }, mapped, effectiveTarget);
  expect(trace).toEqual(["missed", "registry", "callee", "world", "events", "hook", "animal", "events", "push", "push-call"]);
  expect(removed).toEqual([3]);
  expect(removed).not.toBe(hookRemoved);
  expect(events.map(e => e.type)).toEqual(["exile_target_mapped", "voted_out"]);
  expect(mappedExileSummary(mapped, effectiveTarget)).toEqual({ effectiveTarget: null });
  expect(trace.at(-1)).toBe("missed-late");
  expect(resolveMappedExile({
    get world(): never { throw new Error("literal_miss_world"); },
    get eventRegistry(): never { throw new Error("literal_miss_registry"); },
    get events(): never { throw new Error("literal_miss_events"); },
    get animalUnit(): never { throw new Error("literal_no_removed_animal"); },
  }, mapped, effectiveTarget)).toEqual([]);
  const animalEvents: GameEvent[] = [];
  const animalRemoved = resolveMappedExile({ world, events: animalEvents, eventRegistry: { onVotedOut() { return { prevented: false, removed: [3], reason: "literal_animal_proposal" }; } }, animalUnit: {} }, null, 3);
  expect(animalRemoved).toEqual([3]);
  expect(animalEvents).toEqual([]);
  expect(mappedExileSummary(null, 3)).toEqual({});
});

test("mapped or voted_out push failure cannot refund the original one-use mapping or hook prefix", () => {
