});

test("真实婚约要求唯一三阵营规则，未完成分配先于候选结构和日期拒绝", () => {
  const board = ghostBrideBoard(), game = bootstrapGame(board, { fixedRoles: ghostBrideDeck }), trace: string[] = [];
